$sectionId=max(0,(int)($_GET['section_id']??$_POST['section_id']??0));$newsId=max(0,(int)($_GET['news_id']??$_POST['news_id']??0));$section=$sectionId?fetchNewsSection($pdo,$sectionId):null;if($section){$newsId=(int)$section['news_id'];}$news=fetchNewsArticle($pdo,$newsId);if(!$news){header('Location:news.php');exit;}$kind=$section?'news_section_images':'news_images';$ownerType=$section?'news_content_section':'news_article';$ownerId=$section?(int)$section['id']:$newsId;$batch=mediaBatchGetOrCreate($pdo,$kind,$ownerType,$ownerId,'Images for '.($section['subheading']??$news['headline']),'news');
if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'upload';if($action==='upload'){$errors=[];$count=mediaBatchUpload($pdo,$batch,$_FILES['images']??[],['original'=>null,'lg'=>1200,'md'=>600,'sm'=>300,'xs'=>150],$errors);foreach($errors as$error)$alerts[]=['type'=>'danger','message'=>$error];}else{foreach(array_column(mediaBatchImages($pdo,(int)$batch['id'],true),null,'id') as$imageId=>$image){$v=$_POST['image'][$imageId]??null;if(!$v)continue;$pdo->prepare('UPDATE media_batch_images SET title=:title,alt_text=:alt,caption=:caption,display_order=:ord,lightbox_enabled=:lightbox,archived=:archived WHERE id=:id AND batch_id=:batch')->execute([':title'=>trim((string)($v['title']??''))?:null,':alt'=>trim((string)($v['alt_text']??''))?:null,':caption'=>trim((string)($v['caption']??''))?:null,':ord'=>(int)($v['display_order']??100),':lightbox'=>!empty($v['lightbox_enabled']),':archived'=>!empty($v['archived']),':id'=>$imageId,':batch'=>$batch['id']]);}}header('Location:news_images.php?'.($section?'section_id='.$sectionId:'news_id='.$newsId));exit;}
