<div class="d-flex justify-content-between mb-3"><h5><?php echo h($section['subheading']??$news['headline']); ?> — Gallery</h5><a class="btn btn-outline-secondary" href="<?php echo $section?'news_sections.php?news_id='.$newsId:'news_edit.php?id='.$newsId; ?>">Back</a></div><div class="card-soft p-4 mb-4"><form method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="upload"><input type="hidden" name="news_id" value="<?php echo $newsId; ?>"><input type="hidden" name="section_id" value="<?php echo $sectionId; ?>"><input class="form-control" type="file" name="images[]" accept="image/*" multiple required><button class="btn btn-success mt-3">Upload Images</button></form></div><div class="card-soft p-3"><form method="post"><input type="hidden" name="action" value="save"><input type="hidden" name="news_id" value="<?php echo $newsId; ?>"><input type="hidden" name="section_id" value="<?php echo $sectionId; ?>"><table class="table align-middle"><tbody><?php foreach($images as$i=>$image): ?><tr><td><img src="<?php echo h(mediaBatchImageUrl($batch,$image,'sm')); ?>" style="width:180px;max-height:100px;object-fit:cover" class="rounded"></td><td><input class="form-control form-control-sm mb-1" type="number" name="image[<?php echo $image['id']; ?>][display_order]" value="<?php echo $image['display_order']; ?>"><input class="form-control form-control-sm mb-1" name="image[<?php echo $image['id']; ?>][title]" value="<?php echo h($image['title']??''); ?>" placeholder="Title"><input class="form-control form-control-sm mb-1" name="image[<?php echo $image['id']; ?>][alt_text]" value="<?php echo h($image['alt_text']??''); ?>" placeholder="Alt text"><textarea class="form-control form-control-sm" name="image[<?php echo $image['id']; ?>][caption]" placeholder="Caption"><?php echo h($image['caption']??''); ?></textarea></td><td><label><input type="checkbox" name="image[<?php echo $image['id']; ?>][lightbox_enabled]" <?php echo !empty($image['lightbox_enabled'])?'checked':''; ?>> Lightbox</label><br><label><input type="checkbox" name="image[<?php echo $image['id']; ?>][archived]" <?php echo !empty($image['archived'])?'checked':''; ?>> Archived</label></td></tr><?php endforeach; ?></tbody></table><?php if($images): ?><button class="btn btn-success">Save Gallery</button><?php endif; ?></form></div><?php admin_layout_end();
